import "server-only";

// No token scope or environment flag can enable mailbox access in send-only v1.
export function canReadGmail() {
  return false;
}
type ActiveUser = { id: string; deletionRequestedAt?: Date | null };
export function canMarkReplied(
  user: ActiveUser,
  access?: { features: { markReplied: boolean } },
) {
  return (
    !!user.id &&
    !user.deletionRequestedAt &&
    access?.features.markReplied === true
  );
}
export function needsSendOnlyReconnect(user: {
  gmailSendOnlyConsentAt: Date | null;
  gmailScopes: string[];
}) {
  return (
    !user.gmailSendOnlyConsentAt ||
    user.gmailScopes.some(
      (scope) =>
        (scope.startsWith("https://www.googleapis.com/auth/gmail.") ||
          scope === "https://mail.google.com/") &&
        scope !== "https://www.googleapis.com/auth/gmail.send",
    )
  );
}
